 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # The full-width 2-row is a barrier. The colored object slides toward it,
    # then an 8-colored row marks the trailing edge of its final position.
    barriers = [r for r, row in enumerate(g) if all(v == row[0] for v in row) and row[0] == 2]
    if not barriers:
        return g
    br = barriers[0]
    bg = next((v for row in g for v in row if v != 2), 0)
    colors = {v for r in range(h) if r != br for v in g[r] if v not in (bg, 2, 8)}
    if not colors:
        return g
    obj = max(colors, key=lambda c: sum(v == c for row in g for v in row))
    coords = [(r, c) for r in range(h) for c in range(w) if g[r][c] == obj]
    if not coords:
        return g
    above = max(r for r, _ in coords) < br
    dr = 1 if above else -1
    # Translate the shape as far as possible toward the barrier.
    while True:
        moved = {(r + dr, c) for r, c in coords}
        blocked = any(r < 0 or r >= h or g[r][c] not in (bg, obj) for r, c in moved)
        if blocked:
            break
        coords = [(r + dr, c) for r, c in coords]
    for r, c in [(r, c) for r in range(h) for c in range(w) if g[r][c] == obj]:
        g[r][c] = bg
    for r, c in coords:
        g[r][c] = obj
    trailing_row = min(r for r, _ in coords) - 1 if above else max(r for r, _ in coords) + 1
    if 0 <= trailing_row < h:
        g[trailing_row] = [8] * w
    return g

